/**
 * Node 侧共用的落盘原语：原子写 + GLB 文件校验。
 * Runtime 与 runtime-mock 各自实现过一遍，语义必须一致（注册表格式相同，mock 的目录会被真实 Runtime 接着用）。
 */
import { randomUUID } from 'node:crypto';
import { closeSync, existsSync, fsyncSync, openSync, readSync, renameSync, statSync, unlinkSync, writeFileSync } from 'node:fs';
import { dirname, extname, join } from 'node:path';

import { GLB_HEADER_BYTES, assertGlbHeader } from '../glb';

export interface AtomicWriteOptions {
  /** 临时文件的文件名前缀，只为出问题时好认；默认 `atomic`。 */
  temporaryPrefix?: string;
  /** 临时文件的 mode，默认 0o600（注册表里有工作区路径，不给同机其他用户读）。 */
  mode?: number;
}

/**
 * 原子写：同目录临时文件 → fsync → rename 覆盖目标。
 * 临时名带 uuid，多进程/多实例同时写也不会互相踩；失败时 finally 里清掉残留。
 */
export function writeFileAtomicSync(target: string, contents: string | Uint8Array, options: AtomicWriteOptions = {}): void {
  const temporary = join(dirname(target), `.${options.temporaryPrefix ?? 'atomic'}-${randomUUID()}.tmp`);
  let descriptor: number | null = null;
  try {
    descriptor = openSync(temporary, 'wx', options.mode ?? 0o600);
    writeFileSync(descriptor, contents);
    fsyncSync(descriptor);
    closeSync(descriptor);
    descriptor = null;
    renameSyncWithRetry(temporary, target);
  } finally {
    if (descriptor !== null) closeSync(descriptor);
    if (existsSync(temporary)) unlinkSync(temporary);
  }
}

/**
 * Windows 下把临时文件 rename 覆盖到一个刚被写过的已存在文件时，偶尔会被 AV / 索引服务短暂占用一下
 * 导致 EPERM/EBUSY——这类占用通常几十毫秒就释放，重试几次即可，不是真的写坏了或者权限不够。
 *
 * 只做立即重试、不在重试之间同步等待：Runtime 与 mock 都在同一个事件循环上转发 codex 的流式通知，
 * 同步睡眠会连着把输出一起停住。需要退避的高频写入路径应该走异步 rename，而不是把这里改成阻塞。
 */
export function renameSyncWithRetry(source: string, destination: string, maxAttempts = 3): void {
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      renameSync(source, destination);
      return;
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (attempt === maxAttempts || (code !== 'EPERM' && code !== 'EBUSY')) throw error;
    }
  }
}

/** 校验一个 .glb 文件：后缀 + 12 字节头（头里声明的长度必须等于实际文件大小）。只读头，不整体加载。 */
export function validateGlbFile(sourcePath: string): void {
  if (extname(sourcePath).toLowerCase() !== '.glb') throw new Error(`expected a .glb file: ${sourcePath}`);
  const size = statSync(sourcePath).size;
  const header = Buffer.alloc(GLB_HEADER_BYTES);
  const descriptor = openSync(sourcePath, 'r');
  try {
    const bytesRead = readSync(descriptor, header, 0, header.byteLength, 0);
    assertGlbHeader(header.subarray(0, bytesRead), size, sourcePath);
  } finally {
    closeSync(descriptor);
  }
}
